        mockMvc.perform(get("/api/releases/" + releaseId + "/tasks").param("status", "BOGUS"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/api/releases/9999/tasks"))
                .andExpect(status().isNotFound());
    }
