                throw ApiException.conflict("LEASE_HOLDER_MISMATCH",
                        "终结代理与令牌已冻结，非实际终结代理的回执不予受理");
            }
        }
        if (task.firstResult() != request.result()) {
            throw ApiException.conflict("RECEIPT_RESULT_CONFLICT",
